class Character07{private int health;private final int maxHealth;Character07(int m){maxHealth=Math.max(1,m);health=maxHealth;}void takeDamage(int n){if(n>0)health=Math.max(0,health-n);}void heal(int n){if(n>0)health=Math.min(maxHealth,health+n);}int getHealth(){return health;}} public class Week07Problem01{public static void main(String[]z){Character07 c=new Character07(100);c.takeDamage(35);c.heal(10);System.out.println("Health: "+c.getHealth());}}